'use strict';
const R=Rules,C=VTM_CATALOG,O=VTM_OPTIONS,$=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groupNames={physical:'Físicos',social:'Sociais',mental:'Mentais',talents:'Talentos',skills:'Perícias',knowledges:'Conhecimentos'};
const attrLabels={strength:'Força',dexterity:'Destreza',stamina:'Vigor',charisma:'Carisma',manipulation:'Manipulação',appearance:'Aparência',perception:'Percepção',intelligence:'Inteligência',wits:'Raciocínio'};
const attrGroups={physical:['strength','dexterity','stamina'],social:['charisma','manipulation','appearance'],mental:['perception','intelligence','wits']};
const virtueLabels=c=>({moral:c.virtueTypes.moral==='conviction'?'Convicção':'Consciência',restraint:c.virtueTypes.restraint==='instinct'?'Instinto':'Autocontrole',courage:'Coragem'});
const categories={clan:'Clãs e linhagens',bloodline:'Linhagens',road:'Caminhos e trilhas',discipline:'Disciplinas',power:'Poderes de disciplinas',background:'Antecedentes',merit:'Qualidades',flaw:'Defeitos',ritual:'Rituais',path:'Trilhas de magia',archetype:'Arquétipos',rule:'Regras',combination:'Disciplinas combinadas',setting:'Cenário'};
const nav=[['resumo','◈','Visão geral'],['personagem','♜','Identidade e clã'],['atributos','✦','Atributos'],['habilidades','✧','Habilidades'],['vantagens','☾','Disciplinas e vantagens'],['criacao','◇','Criação e evolução'],['sessao','⚄','Mesa de jogo'],['inventario','⚔','Equipamentos'],['catalogo','⌕','Catálogo de opções'],['biblioteca','▤','Biblioteca'],['modificadores','±','Modificadores'],['historico','↶','Histórico de edições']];
const journal=new EditHistory.Journal();let state={characters:[],selected:null},view='resumo',saveTimer,saveChain=Promise.resolve(),storageBlocked=false,lastSave='Salvamento automático',editLabel='Editar ficha',historyReady=false;
let catalogFilter={query:'',category:'',book:'core',page:0},libraryFilter={query:'',book:'',page:0};
const ch=()=>state.characters.find(c=>c.id===state.selected)||state.characters[0];
const num=(v,label='Valor',min=0,integer=true)=>R.number(v,label,min,Number.MAX_SAFE_INTEGER,integer);
const fmt=n=>Number(n??0).toLocaleString('pt-BR',{maximumFractionDigits:6});
const bookTitle=id=>C.books.find(b=>b.id===id)?.title||'Regra da crônica';
const abilityDefs=()=>R.abilityDefinitions||R.abilities?.filter?.(x=>typeof x==='object')||[];
const abilityLabel=key=>abilityDefs().find(a=>a.key===key)?.label||R.labels?.[key]||key;
const attrValue=(c,s,k)=>s.attributes?.[k]??c.attributes[k],abilityValue=(c,s,k)=>s.abilities?.[k]??c.abilities[k];
function stats(c=ch()){const s=R.calculate(c);return {...s,roadScore:s.roadScore??c.roadScore,willpowerMax:s.willpowerMax??s.willpower??c.willpower,xpAvailable:s.xpAvailable??Math.max(0,c.experience.total-c.experience.spent),freebieSpent:s.freebieSpent??s.creation?.freebieSpent??0,freebieRemaining:s.freebieRemaining??s.creation?.freebieRemaining??c.creation.freebieBudget}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5200)}
function updateSave(){const el=$('#save-status');if(el)el.textContent=lastSave}
function historyButtons(){document.querySelectorAll('[data-action="undo"]').forEach(x=>x.disabled=!journal.undo.length);document.querySelectorAll('[data-action="redo"]').forEach(x=>x.disabled=!journal.redo.length)}
function persisted(){return {...R.pack(state.characters),selected:state.selected,audit:journal.serialize()}}
function save(hint=null){R.calculate(ch());if(historyReady){journal.record(state.characters,editLabel,hint?{id:ch().id,key:hint}:null);historyButtons()}ch().updatedAt=new Date().toISOString();lastSave='Salvando…';updateSave();clearTimeout(saveTimer);saveTimer=setTimeout(flushSave,600)}
async function flushSave(){clearTimeout(saveTimer);if(storageBlocked)return;const text=JSON.stringify(persisted());saveChain=saveChain.catch(()=>{}).then(async()=>{if(window.desktop)await desktop.save(text);else{const old=localStorage.getItem('sangue-e-cinzas-dav20');if(old)localStorage.setItem('sangue-e-cinzas-backup',old);localStorage.setItem('sangue-e-cinzas-dav20',text)}lastSave='Todas as alterações salvas';updateSave()}).catch(e=>{lastSave='Falha ao salvar — exporte um backup';updateSave();toast(e.message)});return saveChain}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">SANGUE & CINZAS / DARK AGES V20</div><h1>${title}</h1><p>${sub}</p></div>${actions}</div>`}
function btn(action,label,cls='',attrs=''){return `<button data-action="${action}" class="${cls}" ${attrs}>${label}</button>`}
function opts(list,value){return list.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`}).join('')}
function field(label,key,value,type='text',extra=''){return `<div><label for="f-${key}">${label}</label><input id="f-${key}" data-field="${key}" type="${type}" value="${esc(value)}" ${type==='number'?'step="1"':''} ${extra}></div>`}
function select(label,key,list,value){return `<div><label for="f-${key}">${label}</label><select id="f-${key}" data-field="${key}">${opts(list,value)}</select></div>`}
function area(label,key,value){return `<div><label for="f-${key}">${label}</label><textarea id="f-${key}" data-field="${key}" maxlength="100000">${esc(value)}</textarea></div>`}
function toggle(label,key,value){return `<label class="toggle-label"><input type="checkbox" data-field="${key}" ${value?'checked':''}>${label}</label>`}
function empty(text,action='',label=''){return `<div class="empty"><p>${text}</p>${action?btn(action,label,'primary'):''}</div>`}
function sourceLink(i){return i.book?btn('source','Consultar fonte','ghost small',`data-book="${esc(i.book)}" data-page="${i.page||1}"`):''}
function validation(s){return s.warnings.length?s.warnings.map(x=>`<div class="warn">${esc(x)}</div>`).join(''):'<div class="okay">✓ Nenhuma pendência numérica encontrada.</div>'}
function render(){const c=ch(),s=stats(c);patchApp(`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">S</div><div><strong>Sangue & Cinzas</strong><small>DARK AGES V20</small></div></div><div><div class="eyebrow side-label">AS NOITES DE SEU CAINITA</div><nav class="nav" aria-label="Navegação principal">${nav.map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span class="nav-symbol">${icon}</span>${label}</button>`).join('')}</nav></div><div><div class="eyebrow side-label">PERSONAGENS · ${state.characters.length}</div><div class="roster">${state.characters.map(x=>`<button data-character="${x.id}" class="${c.id===x.id?'selected':''}">◇ ${esc(x.name)}</button>`).join('')}</div>${btn('new','+ Novo personagem','ghost small','style="width:100%;margin-top:8px"')}</div><div class="sidebar-bottom">Disponível offline<br>${C.libraryReady?`${C.books.length} PDFs · ${fmt(C.pageCount)} páginas`:'Acervo não configurado'}<br><span id="save-status">${lastSave}</span></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">Crônica / <strong>${esc(c.name)}</strong></span><div class="actions">${btn('undo','↶','small',`aria-label="Desfazer" title="Desfazer" ${journal.undo.length?'':'disabled'}`)}${btn('redo','↷','small',`aria-label="Refazer" title="Refazer" ${journal.redo.length?'':'disabled'}`)}${btn('import','Importar','ghost small')}${btn('export','Compartilhar ficha','small')}${btn('pdf','↓ PDF','primary small')}</div></header><div class="content">${({resumo:summary,personagem:identity,atributos:attributesPage,habilidades:abilitiesPage,vantagens:advantages,criacao:creationPage,sessao:session,inventario:inventoryPage,catalogo:catalogPage,biblioteca:libraryPage,modificadores:bonusesPage,historico:historyPage})[view](c,s)}</div></main></div>`)}
function guide(c,s){const phase=c.creation.phase;return `<section class="panel section-gap"><div class="panel-head"><h2>Da vida mortal às noites eternas</h2><span class="chip red">${phase==='allocation'?'DISTRIBUIÇÃO INICIAL':phase==='freebies'?'PONTOS DE BÔNUS':'EM CRÔNICA'}</span></div><div class="guide-steps">${[['1. Identidade e clã','personagem'],['2. Atributos e habilidades','atributos'],['3. Vantagens e virtudes','vantagens'],['4. Conferir e finalizar','criacao']].map(([label,v])=>btn('guide',label,'ghost',`data-goto="${v}"`)).join('')}</div><p class="hint">Distribua os pontos iniciais. Em Criação e evolução, conclua essa distribuição para separar as compras com pontos de bônus. Alterações posteriores ficam no histórico.</p></section>`}
function summary(c,s){return heading('A noite tem memória.','Crie seu Cainita, acompanhe sua crônica e consulte o acervo.',`<span class="chip red">${esc(c.clan||'SEM CLÃ')} · ${c.generation}ª GERAÇÃO</span>`)+`<div class="grid hero-grid"><section class="panel identity"><div class="avatar">${c.portrait?`<img src="${c.portrait}" alt="Retrato do personagem">`:'♜'}</div><div><span class="chip">VAMPIRO: IDADE DAS TREVAS</span><h2>${esc(c.name)}</h2><p>${esc(c.concept||'Toda imortalidade começa com uma história.')}</p>${btn('guide','Editar identidade','ghost small','data-goto="personagem"')}</div></section><section class="panel"><div class="eyebrow">CAMINHO E FORÇA DE VONTADE</div><div class="stat-grid"><div class="stat"><small>${esc(roadLabel(c.road))}</small><strong>${fmt(s.roadScore)}</strong></div><div class="stat"><small>Força de Vontade</small><strong>${fmt(c.resources.willpower)} / ${fmt(s.willpowerMax)}</strong></div><div class="stat"><small>Sangue</small><strong>${fmt(c.resources.blood)} / ${s.bloodMax==null?'a definir':fmt(s.bloodMax)}</strong></div></div></section></div><div class="grid cols2 section-gap"><section class="panel"><div class="panel-head"><h2>Seu lugar nas noites</h2>${btn('guide','Ver vantagens →','ghost small','data-goto="vantagens"')}</div><p>${esc(clanLabel(c.clan))} · ${esc(c.chronicle||'Crônica sem nome')}<br>Natureza: ${esc(c.nature||'—')} · Comportamento: ${esc(c.demeanor||'—')}</p><div class="stat-grid"><div class="stat"><small>Iniciativa</small><strong>${fmt(s.initiative)} + 1d10</strong></div><div class="stat"><small>Vitalidade</small><strong>${esc(s.healthLabel||healthName(c))}</strong></div><div class="stat"><small>PE disponíveis</small><strong>${fmt(s.xpAvailable)}</strong></div></div><div class="divider"></div><h3>Disciplinas</h3><div class="actions">${c.disciplines.map(i=>`<span class="chip">${esc(i.name)} ${i.rating}</span>`).join('')||'<p>Ainda não há disciplinas registradas.</p>'}</div><p class="hint">Sangue por turno: ${s.bloodPerTurn==null?'a definir':fmt(s.bloodPerTurn)}. Limite de característica pela geração: ${fmt(s.traitMax)}. Bônus e regras da crônica podem ser registrados sem cortes silenciosos.</p></section><section class="panel"><div class="panel-head"><h2>Conferência da criação</h2>${btn('guide','Conferir pontos →','ghost small','data-goto="criacao"')}</div>${validation({...s,warnings:s.warnings.slice(0,7)})}${s.warnings.length>7?`<p class="hint">Mais ${s.warnings.length-7} avisos em Criação e evolução.</p>`:''}</section></div>${guide(c,s)}`}
function clanLabel(name){const i=O.clans?.find(x=>x.name===name);return i?.label||name||'Sem clã'}
function roadLabel(name){return O.roads?.find(x=>x.name===name)?.label||name||'Caminho'}
function identity(c){const clan=O.clans?.find(x=>x.name===c.clan),road=O.roads?.find(x=>x.name===c.road);return heading('A criatura e quem ela foi.','Identidade, linhagem, crenças e vínculos da sua história.')+`<div class="grid cols2"><section class="panel"><h2>Identidade</h2><div class="field-grid">${field('Nome','name',c.name,'text','maxlength="200"')}${field('Jogador','player',c.player)}${field('Crônica','chronicle',c.chronicle)}${field('Conceito','concept',c.concept)}${select('Clã / linhagem','clan',[['','Sem clã / personalizado'],...(O.clans||[]).map(i=>[i.name,i.label||i.name]),...(!clan&&c.clan?[[c.clan,c.clan]]:[])],c.clan)}${field('Geração','generation',c.generation,'number','min="3"')}${field('Senhor / sire','sire',c.sire)}${field('Seita / corte / domínio','sect',c.sect)}${field('Nascimento / idade aparente','birth',c.birth)}${field('Abraço / idade vampírica','embrace',c.embrace)}${field('Refúgio','haven',c.haven)}${field('Preferência de sangue / restrição','bloodPreference',c.bloodPreference||'')}</div><div class="actions section-gap">${btn('portrait','Escolher retrato','small')}${c.portrait?btn('remove-portrait','Remover retrato','ghost small'):''}${btn('duplicate','Duplicar','ghost small')}${btn('delete-character','Excluir','danger ghost small')}</div><p class="hint">Retratos PNG, JPG ou WebP ficam na ficha compartilhada. Até 4 MB.</p></section><section class="panel"><h2>O que guia seu Cainita</h2><div class="field-grid">${field('Natureza','nature',c.nature,'text','list="archetypes"')}${field('Comportamento','demeanor',c.demeanor,'text','list="archetypes"')}${select('Caminho / trilha moral','road',[...(O.roads||[]).map(i=>[i.name,i.label||i.name]),...(!road&&c.road?[[c.road,c.road]]:[])],c.road)}</div><datalist id="archetypes">${(O.archetypes||[]).map(x=>`<option value="${esc(typeof x==='string'?x:x.label||x.name)}"></option>`).join('')}</datalist><div class="divider"></div><h3>${esc(clanLabel(c.clan))}</h3><p class="hint">${esc(clan?.weakness||'Registre a fraqueza da linhagem e confira a fonte. O mestre resolve as exceções narrativas.')}</p><p class="hint">Disciplinas do clã: ${esc(clan?.disciplines?.join(', ')||'definidas pelo narrador')}.</p><div class="actions section-gap">${clan?btn('clan-disciplines','Adicionar disciplinas do clã','small'):''}${clan?sourceLink(clan):''}</div><div class="divider"></div><h3>${esc(roadLabel(c.road))}</h3><p class="hint">Virtudes: ${Object.values(virtueLabels(c)).join(', ')}. ${esc(road?.summary||'Consulte as convicções e a hierarquia de pecados na fonte. A escolha ajusta os nomes das virtudes; seus valores permanecem editáveis.')}</p>${road?sourceLink(road):''}</section></div><div class="grid cols2 section-gap"><section class="panel">${area('Aparência, personalidade e sinais do Abraço','appearance',c.appearance)}</section><section class="panel">${area('Vida mortal, Abraço e história','history',c.history)}</section></div><section class="panel section-gap">${area('Fraqueza da linhagem e exceções da crônica','weakness',c.weakness||'')}<div class="section-gap">${area('Anotações e vínculos','notes',c.notes)}</div></section>`}
function trait(group,k,label,value,final,limit=5,c=ch()){const bonus=final-value;return `<div class="trait-row"><div class="trait-top"><label for="trait-${group}-${k}">${esc(label)}</label><div class="trait-controls">${btn('trait-step','−','',`data-group="${group}" data-key="${k}" data-delta="-1" aria-label="Diminuir ${esc(label)}"`)}<input id="trait-${group}-${k}" data-trait="${group}" data-key="${k}" type="number" value="${value}" min="0" step="1" aria-label="${esc(label)}">${btn('trait-step','+','',`data-group="${group}" data-key="${k}" data-delta="1" aria-label="Aumentar ${esc(label)}"`)}</div></div><div class="dots">${Array.from({length:Math.max(5,Math.min(10,limit))},(_,n)=>btn('trait-dot','',n<value?'filled':'',`data-group="${group}" data-key="${k}" data-value="${n+1}" aria-label="${esc(label)} ${n+1}"`)).join('')}</div>${bonus?`<div class="trait-extra">Com modificadores: ${fmt(final)} (${bonus>=0?'+':''}${fmt(bonus)})</div>`:''}${['attributes','abilities'].includes(group)?`<input class="specialty" data-specialty="${k}" value="${esc(c.specialties?.[k]||'')}" placeholder="Especialidade (normalmente 4+)" aria-label="Especialidade de ${esc(label)}">`:''}</div>`}
function prioritySelect(type,group,c){const order=c.creation[type+'Priorities'],index=order.indexOf(group);return `<div class="allocation"><span class="rating-total">${groupNames[group]}</span><select data-priority="${type}" data-group="${group}" ${c.creation.phase!=='allocation'?'disabled':''} aria-label="Prioridade de ${groupNames[group]}">${opts([['0','Primários · '+(type==='attribute'?7:13)],['1','Secundários · '+(type==='attribute'?5:9)],['2','Terciários · '+(type==='attribute'?3:5)]],String(index))}</select></div>`}
function attributesPage(c,s){return heading('A marca do sangue.','Atributos Físicos, Sociais e Mentais: uma base de 1 e distribuição inicial 7 / 5 / 3.')+`<div class="grid cols3">${Object.entries(attrGroups).map(([group,keys])=>`<section class="panel"><h2>${groupNames[group]}</h2>${prioritySelect('attribute',group,c)}<div class="rating-list">${keys.map(k=>trait('attributes',k,attrLabels[k],c.attributes[k],attrValue(c,s,k),s.traitMax,c)).join('')}</div></section>`).join('')}</div><p class="hint">Os círculos oferecem escolhas rápidas; o campo numérico permite valores maiores. O limite da geração gera avisos. Especialidades só alteram os 10 quando marcadas na rolagem.</p>${guide(c,s)}`}
function abilitiesPage(c,s){return heading('O que você aprendeu nas noites.','Talentos, Perícias e Conhecimentos. Distribuição inicial 13 / 9 / 5; máximo inicial de 3.')+`<div class="grid cols3">${['talents','skills','knowledges'].map(group=>`<section class="panel"><h2>${groupNames[group]}</h2>${prioritySelect('ability',group,c)}<div class="rating-list">${abilityDefs().filter(a=>a.group===group).map(a=>trait('abilities',a.key,a.label,c.abilities[a.key],abilityValue(c,s,a.key),s.traitMax,c)).join('')}</div></section>`).join('')}</div><section class="panel section-gap"><h2>Habilidades adicionais</h2><p class="hint">Para profissões e conhecimentos da crônica, use antecedentes, especialidades ou um modificador nomeado para a rolagem e descreva a regra. As habilidades do núcleo seguem a ficha de Dark Ages V20.</p>${btn('guide','Registrar regra ou modificador','small','data-goto="modificadores"')}</section>`}
const collectionLabels={disciplines:'Disciplinas',backgrounds:'Antecedentes',paths:'Trilhas e referências de poderes',rituals:'Rituais',merits:'Qualidades',flaws:'Defeitos'};
function collection(c,key){return `<section class="panel"><div class="panel-head"><h2>${collectionLabels[key]}</h2>${btn('new-option','+ Adicionar','small',`data-list="${key}"`)}</div><div class="list">${c[key].map(i=>`<article class="list-item"><div><h3>${esc(i.name)} <span class="chip">${['merits','flaws'].includes(key)?fmt(i.cost)+' PT':i.kind==='ritual'?'NÍVEL '+i.rating:fmt(i.rating)+' ●'}</span>${i.inClan?'<span class="chip red">DO CLÃ</span>':''}</h3><small>${esc(bookTitle(i.book))}${i.book?' · PDF p. '+i.page:''}${i.kind?' · '+esc(i.kind):''}</small>${i.notes?`<p>${esc(i.notes)}</p>`:''}</div><div class="actions">${btn('edit-option','Detalhes','small',`data-list="${key}" data-id="${i.id}"`)}${btn('remove-option','Remover','danger ghost small',`data-list="${key}" data-id="${i.id}"`)}</div></article>`).join('')||empty('Nenhuma opção registrada.')}</div></section>`}
function advantages(c,s){const labels=virtueLabels(c);return heading('Poder, influência e convicção.','Disciplinas, antecedentes, qualidades e defeitos com escolhas e referências.',btn('guide','Buscar no catálogo','primary','data-goto="catalogo"'))+`<div class="grid cols2">${collection(c,'disciplines')}${collection(c,'backgrounds')}</div><div class="grid cols2 section-gap"><section class="panel"><h2>Virtudes</h2><div class="field-grid">${select('Virtude moral','virtueTypes.moral',[['conscience','Consciência'],['conviction','Convicção']],c.virtueTypes.moral)}${select('Contenção da Besta','virtueTypes.restraint',[['selfControl','Autocontrole'],['instinct','Instinto']],c.virtueTypes.restraint)}</div><div class="rating-list section-gap">${Object.entries(labels).map(([k,label])=>trait('virtues',k,label,c.virtues[k],c.virtues[k],5,c)).join('')}</div><p class="hint">Uma base de 1 em cada virtude, incluindo as alternativas de Dark Ages V20; mais 7 pontos. Na distribuição inicial, Caminho = virtude moral + contenção; Força de Vontade = Coragem.</p></section><section class="panel"><h2>Caminho e Força de Vontade</h2><div class="field-grid">${field('Caminho permanente','roadScore',s.roadScore,'number',c.creation.phase==='allocation'?'disabled':'')}${field('Força de Vontade permanente','willpower',s.willpowerMax,'number',c.creation.phase==='allocation'?'disabled':'')}</div><p class="hint">Na distribuição inicial esses valores são derivados. Após concluir essa etapa, pontos de bônus e experiência podem aumentá-los. Comprar Virtudes depois não aumenta Caminho nem Força de Vontade automaticamente.</p>${btn('guide','Ver pontos de criação','small','data-goto="criacao"')}</section></div><div class="grid cols2 section-gap">${collection(c,'merits')}${collection(c,'flaws')}</div><div class="grid cols2 section-gap">${collection(c,'paths')}${collection(c,'rituals')}</div>`}
function allocationCounts(c){const attrs=Object.fromEntries(Object.entries(attrGroups).map(([g,keys])=>[g,keys.reduce((t,k)=>t+Math.max(0,c.attributes[k]-(c.clan==='Nosferatu'&&k==='appearance'?0:1)),0)]));const abilities=Object.fromEntries(['talents','skills','knowledges'].map(g=>[g,abilityDefs().filter(a=>a.group===g).reduce((t,a)=>t+c.abilities[a.key],0)]));return {attrs,abilities,disciplines:c.disciplines.reduce((n,i)=>n+i.rating,0),backgrounds:c.backgrounds.reduce((n,i)=>n+i.rating,0),virtues:Object.values(c.virtues).reduce((n,v)=>n+Math.max(0,v-1),0)}}
function creationPage(c,s){const counts={attrs:s.allocation.attributes,abilities:s.allocation.abilities,disciplines:s.allocation.disciplines,backgrounds:s.allocation.backgrounds,virtues:s.allocation.virtues},phase=c.creation.phase;return heading('Cada ponto conta uma história.','Distribuição inicial, pontos de bônus e evolução com registro de compras.')+`<div class="grid cols2"><section class="panel"><h2>Etapas da criação</h2><div class="field-grid">${select('Modo de regras','rulesMode',[['standard','Padrão: avisar sobre limites'],['free','Livre: regras da crônica']],c.rulesMode)}${field('Pontos de bônus da crônica','creation.freebieBudget',c.creation.freebieBudget,'number')}${field('Crédito máximo de Defeitos','creation.flawCreditLimit',c.creation.flawCreditLimit,'number')}</div><p class="hint">Etapa atual: <strong>${phase==='allocation'?'Distribuição inicial':phase==='freebies'?'Compras com pontos de bônus':'Em crônica'}</strong>. Limites de campanha geram avisos, sem reduzir valores. Números que não possam ser calculados com segurança são recusados com uma mensagem.</p><div class="actions section-gap">${phase==='allocation'?btn('freeze-creation','Concluir distribuição inicial','primary'):phase==='freebies'?btn('enter-play','Finalizar criação','primary'):''}${phase!=='allocation'?btn('reset-creation','Redefinir base de criação','ghost small'):''}</div><p class="hint">Concluir a distribuição guarda uma cópia dos valores iniciais. Os aumentos seguintes são cobrados como pontos de bônus; compras de experiência têm registro próprio. Redefinir a base é uma ação manual da crônica e pode ser desfeita.</p><div class="divider"></div><h3>Pontos de bônus</h3><div class="score-num">${fmt(s.freebieSpent)} <small>gastos / ${fmt(c.creation.freebieBudget)} + defeitos válidos</small></div><p class="hint">Saldo calculado: ${fmt(s.freebieRemaining)}. Custos: atributo 5, habilidade 2, disciplina 7, antecedente 1, virtude 2, Caminho 2 e Força de Vontade 1. A origem de aumentos comprados com experiência fica no registro.</p>${sourceLink({book:'core',page:157})}<div class="divider"></div><h3>Limites da crônica</h3><div class="field-grid">${field('Limite de características (vazio = geração)','campaign.traitLimit',c.campaign.traitLimit??'','number')}${field('Sangue máximo (vazio = geração)','campaign.bloodMax',c.campaign.bloodMax??'','number')}${field('Sangue por turno (vazio = geração)','campaign.bloodPerTurn',c.campaign.bloodPerTurn??'','number')}</div><div class="actions section-gap">${btn('sync-generation','Sincronizar geração pelo antecedente','small')}</div><p class="hint">A geração padrão é 12 menos os pontos do antecedente Geração. Diablerie e ajustes do narrador podem ser registrados manualmente.</p></section><section class="panel"><h2>Distribuição registrada</h2><div class="list">${Object.entries(counts.attrs).map(([g,v])=>`<div class="list-item">Atributos ${groupNames[g]}<strong>${v} / ${[7,5,3][s.allocation.base.attributePriorities.indexOf(g)]}</strong></div>`).join('')}${Object.entries(counts.abilities).map(([g,v])=>`<div class="list-item">Habilidades ${groupNames[g]}<strong>${v} / ${[13,9,5][s.allocation.base.abilityPriorities.indexOf(g)]}</strong></div>`).join('')}<div class="list-item">Disciplinas iniciais<strong>${counts.disciplines} / 4</strong></div><div class="list-item">Antecedentes iniciais<strong>${counts.backgrounds} / 5</strong></div><div class="list-item">Virtudes além da base<strong>${counts.virtues} / 7</strong></div></div><p class="hint">Este painel mostra a distribuição inicial: a base guardada após concluir essa etapa. Os aumentos seguintes são separados como compras.</p></section></div><div class="grid cols2 section-gap"><section class="panel"><div class="panel-head"><h2>Experiência</h2>${btn('buy-xp','Comprar aumento','primary small')}</div><div class="stat-grid"><div class="stat"><small>Recebidos</small><strong>${fmt(c.experience.total)}</strong></div><div class="stat"><small>Gastos</small><strong>${fmt(c.experience.spent)}</strong></div><div class="stat"><small>Disponíveis</small><strong>${fmt(s.xpAvailable)}</strong></div></div><div class="actions section-gap"><input id="xp-amount" class="inline-num" type="number" min="1" value="1" aria-label="Experiência a receber">${btn('gain-xp','Receber PE','small')}</div><div class="divider"></div><div class="journal">${c.experience.ledger.slice().reverse().map(i=>`<div><small>${esc(i.at||i.date||'')} · ${i.cost} PE</small>${esc(i.label||xpLabel(i,c))}: ${i.from} → ${i.to}${i.story?' · '+esc(i.story):''}${i.notes?'\n'+esc(i.notes):''}</div>`).join('')||'<p class="hint">Compras com experiência aparecerão aqui.</p>'}</div></section><section class="panel"><h2>Conferência da ficha</h2>${validation(s)}<div class="divider"></div>${btn('backup','Exportar backup de todos','small')}<p class="hint">Pré-requisitos narrativos, rituais e exceções dos suplementos dependem do narrador. Consulte a fonte e registre os ajustes em Modificadores.</p></section></div>`}
function xpLabel(i,c){return i.type==='attribute'?attrLabels[i.key]:i.type==='ability'?abilityLabel(i.key):i.type==='virtue'?virtueLabels(c)[i.key]:['road','willpower'].includes(i.type)?({road:'Caminho',willpower:'Força de Vontade'}[i.type]):[...c.disciplines,...c.paths,...c.backgrounds].find(x=>x.id===i.key)?.name||i.key}
const healthLevels=['Escoriado','Machucado','Ferido','Ferido gravemente','Espancado','Aleijado','Incapacitado'];
function healthName(c){const n=c.health.bashing+c.health.lethal+c.health.aggravated;return c.health.state==='finalDeath'?'Morte final':c.health.state==='torpor'?'Torpor':n?healthLevels[Math.min(6,n-1)]:'Ileso'}
function healthPanel(c,s){const marks=[...Array(c.health.aggravated).fill('aggravated'),...Array(c.health.lethal).fill('lethal'),...Array(c.health.bashing).fill('bashing')];return `<div class="health-list">${healthLevels.map((label,n)=>`<div class="health-level ${marks[n]||''}"><span>${label} ${n===1||n===2?'(−1)':n===3||n===4?'(−2)':n===5?'(−5)':''}</span><span class="health-mark">${({bashing:'/',lethal:'X',aggravated:'✱'})[marks[n]]||'□'}</span></div>`).join('')}</div><p class="hint">${healthName(c)}. Penalidade de ferimentos: ${fmt(s.healthPenalty)}. O dano recebido aqui já passou pela absorção; a divisão de dano contundente é uma opção abaixo.</p>`}
function session(c,s){return heading('Conduza a noite.','Sangue, Força de Vontade, vitalidade e rolagens sem sair da ficha.')+`<div class="grid cols2"><section class="panel"><h2>Recursos</h2><div class="grid cols2"><div class="resource"><label for="blood-current">Reserva de sangue</label><strong>${fmt(c.resources.blood)}</strong> <small>/ ${s.bloodMax==null?'a definir':fmt(s.bloodMax)}</small><input id="blood-current" data-resource="blood" type="number" min="0" ${s.bloodMax==null?'':`max="${s.bloodMax}"`} value="${c.resources.blood}" aria-label="Sangue atual"><div class="actions"><input id="blood-amount" class="inline-num" type="number" min="0" value="1" data-preserve="true" aria-label="Quantidade de sangue">${btn('spend-blood','Gastar','small')}${btn('gain-blood','Alimentar','small')}</div></div><div class="resource"><label for="wp-current">Força de Vontade temporária</label><strong>${fmt(c.resources.willpower)}</strong> <small>/ ${fmt(s.willpowerMax)}</small><input id="wp-current" data-resource="willpower" type="number" min="0" max="${s.willpowerMax}" value="${c.resources.willpower}" aria-label="Força de Vontade atual"><div class="actions">${btn('spend-willpower','Gastar 1','small')}${btn('restore-willpower','Recuperar 1','small')}</div></div></div><p class="hint">Máximo por geração: ${s.bloodMax==null?'a definir pelo narrador':fmt(s.bloodMax)+' pontos de sangue'}; por turno: ${s.bloodPerTurn==null?'a definir':fmt(s.bloodPerTurn)}. Alimentação e recuperação dependem da ficção. Gastar Força de Vontade numa rolagem garante um sucesso e debita 1 ponto.</p><div class="actions section-gap">${btn('start-night','Despertar na próxima noite','small')}${btn('initial-blood','Sangue inicial: 1d10 + antecedentes','ghost small')}${btn('next-turn','Avançar turno','small')}${btn('end-scene','Encerrar cena','small')}</div><div class="divider"></div><h3>Condições narrativas</h3><div class="actions">${['Frenesi','Rötschreck','Estacado','Inconsciente','Envenenado','Presença ativa','Dominação'].map(x=>btn('condition',esc(x),c.conditions.includes(x)?'primary small':'small',`data-condition="${esc(x)}"`)).join('')}</div><p class="hint">Marcadores narrativos não acrescentam penalidades automaticamente. Registre efeitos específicos em Modificadores. Torpor e Morte final pertencem ao controle de vitalidade.</p></section><section class="panel"><h2>Vitalidade</h2>${healthPanel(c,s)}<p class="hint">Absorção: contundente ${s.soak.bashing}, letal ${s.soak.lethal}, agravado ${s.soak.aggravated}; fogo/luz solar ${s.soak.fireSunlight}. Armaduras só protegem dos danos compatíveis. Torpor pelo Caminho: ${esc(s.torporLength)}.</p><div class="field-grid section-gap"><div><label for="damage-type">Tipo de dano</label><select id="damage-type" data-preserve="true">${opts([['bashing','Contundente'],['lethal','Letal'],['aggravated','Agravado']],'lethal')}</select></div><div><label for="damage-amount">Dano após absorção</label><input id="damage-amount" type="number" min="0" value="1" data-preserve="true"></div></div><label class="toggle-label section-gap"><input id="halve-bashing" type="checkbox" checked>Dividir dano contundente por 2 (arredondar para baixo)</label><div class="actions section-gap">${btn('apply-damage','Aplicar dano','primary')}${btn('heal','Curar 1 nível','small')}</div><label class="toggle-label section-gap"><input id="heal-rested" type="checkbox">Repousou um dia completo (cura de agravado)</label><div class="field-grid section-gap">${select('Estado','health.state',[['active','Ativo'],['torpor','Torpor'],['finalDeath','Morte final']],c.health.state)}</div>${btn('reset-health','Redefinir vitalidade','ghost small','style="margin-top:12px"')}<p class="hint">Curar contundente/letal custa 1 ponto de sangue por nível. Agravado requer repouso e custo próprio. A vitalidade controla agravamento e torpor; o narrador determina as condições de despertar.</p></section></div><section class="panel section-gap"><div class="panel-head"><h2>Dados da noite</h2><span class="chip">D10 · DIFICULDADE PADRÃO 6</span></div><div class="field-grid"><div><label for="roll-mode">Tipo de rolagem</label><select id="roll-mode" data-preserve="true">${opts([['normal','Ação / teste normal'],['soak','Absorção (sem ferimentos ou falha crítica)'],['damage','Dano (sem falha crítica)']],'normal')}</select></div><div><label for="roll-attribute">Atributo</label><select id="roll-attribute" data-preserve="true">${opts([['','Sem atributo'],...Object.entries(attrLabels)],'dexterity')}</select></div><div><label for="roll-ability">Habilidade</label><select id="roll-ability" data-preserve="true">${opts([['','Sem habilidade'],...abilityDefs().map(a=>[a.key,a.label])],'melee')}</select></div><div><label for="roll-pool">Reserva manual (vazia = atributo + habilidade)</label><input id="roll-pool" data-preserve="true" type="number" min="0" value=""></div><div><label for="roll-difficulty">Dificuldade</label><input id="roll-difficulty" data-preserve="true" type="number" min="2" max="10" value="6"></div><div><label for="roll-modifier">Bônus / redutor situacional de dados</label><input id="roll-modifier" data-preserve="true" type="number" value="0"></div><div><label for="roll-purpose">Descrição do teste</label><input id="roll-purpose" data-preserve="true" placeholder="Ex.: ataque de espada, percepção, disciplina"></div></div><div class="actions section-gap"><label class="toggle-label"><input id="roll-specialty" type="checkbox">Especialidade aplicável: 10 vale dois sucessos</label><label class="toggle-label"><input id="roll-willpower" type="checkbox">Gastar 1 Força de Vontade</label><label class="toggle-label"><input id="roll-reflexive" type="checkbox">Teste reflexivo (sem penalidade de ferimentos)</label></div><div class="actions section-gap">${btn('roll','⚄ Rolar reserva','primary')}${btn('initiative','Rolar iniciativa','small')}</div><div id="last-roll" class="section-gap" aria-live="polite"></div><p class="hint">Cada dado que atinge a dificuldade é um sucesso; cada 1 cancela um. Se houve sucessos nos dados e todos foram cancelados, o resultado é falha simples. Falha crítica exige nenhum sucesso original e pelo menos um 1. A dificuldade 10 é excepcional.</p></section><div class="grid cols2 section-gap"><section class="panel"><div class="panel-head"><h2>Registro de rolagens</h2>${btn('clear-rolls','Limpar','ghost small')}</div><div class="journal">${c.rolls.slice().reverse().map(x=>`<div><small>${esc(x.at||x.date||'')}</small>${esc(x.label||'Registro')} — ${esc(x.explanation||x.text||'')}</div>`).join('')||'<p>Nenhum teste registrado.</p>'}</div></section><section class="panel"><h2>Diário da crônica</h2><textarea id="journal-text" data-preserve="true" placeholder="Pactos, encontros, dívidas e acontecimentos…" aria-label="Nova anotação"></textarea>${btn('journal','Registrar na crônica','small','style="margin-top:10px"')}<div class="journal section-gap">${c.journal.slice().reverse().map(x=>`<div><small>${esc(x.at||x.date||'')}</small>${esc(x.text)}</div>`).join('')}</div></section></div>`}
function inventoryPage(c){const weight=c.inventory.reduce((n,i)=>n+i.weight*i.quantity,0);return heading('O que acompanha sua jornada.','Armas, armaduras, objetos, riquezas e informações de combate.',btn('new-equipment','+ Novo item','primary'))+`<section class="panel"><div class="panel-head"><h2>Equipamentos</h2><span class="chip">${fmt(weight)} KG REGISTRADOS</span></div><div class="list">${c.inventory.map(i=>`<div class="list-item"><div><h3>${esc(i.name)} ${i.equipped?'<span class="chip green">EQUIPADO</span>':''}</h3><small>Quantidade ${fmt(i.quantity)} · ${fmt(i.weight)} kg/un. ${i.damage?' · Dano: '+esc(i.damage):''} ${i.armor?' · Armadura: '+esc(i.armor):''}</small><p>${esc(i.notes)}</p></div><div class="actions">${btn('edit-equipment','Editar','small',`data-id="${i.id}"`)}${btn('remove-equipment','Remover','danger ghost small',`data-id="${i.id}"`)}</div></div>`).join('')||empty('Adicione os itens do seu Cainita.')}</div><p class="hint">Dano, proteção e penalidades das armas/armaduras são descritivos; use os atributos, habilidades e modificadores correspondentes ao teste. Riquezas e status pertencem aos Antecedentes.</p></section>`}
function catalogPage(){if(!C.libraryReady)return heading('Catálogo de opções','Adicione seus próprios livros para consultar o acervo.')+empty('Esta edição de código-fonte não inclui os PDFs nem o texto dos livros. Consulte o README para preparar sua biblioteca local. A criação, os dados e o PDF completo já estão disponíveis.');const result=searchResult('catalog',catalogFilter),pages=Math.max(1,Math.ceil(result.total/30));return heading('Os poderes das noites antigas.','Clãs, caminhos, disciplinas, rituais e opções extraídas do acervo.')+`<div class="filters"><input id="catalog-search" value="${esc(catalogFilter.query)}" aria-label="Buscar no catálogo" placeholder="Nome, regra ou termo em português/inglês…"><select id="catalog-category" aria-label="Categoria">${opts([['','Todas as categorias'],...Object.entries(categories)],catalogFilter.category)}</select><select id="catalog-book" aria-label="Livro">${opts([['','Todos os livros'],...C.books.map(b=>[b.id,b.title])],catalogFilter.book)}</select></div><div class="panel-head"><span class="muted">${result.pending?'Preparando pesquisa…':result.error?'Pesquisa indisponível':fmt(result.total)+' opções encontradas'}</span><span class="chip">LIVRO E PÁGINA VISÍVEIS</span></div><div class="catalog-grid">${result.rows.map(e=>`<article class="catalog-card"><div class="actions"><span class="chip">${esc(categories[e.category]||e.category)}</span>${e.cost!=null?`<span class="chip">${esc(e.cost)} PONTOS</span>`:''}</div><h3>${esc(e.label||e.name)}</h3><p>${esc(e.summary||e.text)}</p><small>${esc(bookTitle(e.book))} · PDF p. ${e.page}${e.ocr?' · OCR':''}</small><div class="actions">${btn('entry','Consultar','ghost small',`data-id="${e.id}"`)}${btn('add-entry','+ Adicionar','primary small',`data-id="${e.id}"`)}</div></article>`).join('')}</div>${!result.pending&&!result.rows.length?empty('Nenhuma opção encontrada. Experimente outro livro ou o nome no idioma original.'):''}<div class="actions section-gap">${btn('catalog-prev','← Anterior','small',catalogFilter.page===0?'disabled':'')}<small>Página ${catalogFilter.page+1} de ${pages}</small>${btn('catalog-next','Próxima →','small',catalogFilter.page>=pages-1?'disabled':'')}</div><p class="footer-note">Catálogo extraído dos PDFs, com seleção revisada de clãs, caminhos e opções básicas. O Companion fornecido contém tradução automática e páginas recuperadas por OCR. Confira custos, exceções e linguagem no PDF original.</p>`}
function libraryPage(){if(!C.libraryReady)return heading('Biblioteca','Adicione seus próprios livros para consultar o acervo.')+empty('Esta edição de código-fonte não inclui os PDFs nem o texto dos livros. Consulte o README para preparar sua biblioteca local. A criação, os dados e o PDF completo já estão disponíveis.');const result=searchResult('library',libraryFilter),pages=Math.max(1,Math.ceil(result.total/30));return heading('Uma biblioteca entre sombras.','Texto integral pesquisável e acesso aos quatro PDFs, sem conexão com a internet.')+`<div class="filters"><input id="library-search" value="${esc(libraryFilter.query)}" aria-label="Pesquisar nos livros" placeholder="Pesquise no texto completo dos livros…"><select id="library-book" aria-label="Livro da biblioteca">${opts([['','Todo o acervo'],...C.books.map(b=>[b.id,b.title])],libraryFilter.book)}</select></div>${libraryFilter.query?`<section class="panel"><div class="panel-head"><h2>${result.pending?'Preparando pesquisa…':fmt(result.total)+' páginas encontradas'}</h2></div><div class="list">${result.rows.map(p=>`<div class="list-item"><div><h3>${esc(bookTitle(p.book))} · PDF p. ${p.page}</h3><p>${esc(p.text)}</p><small>${p.ocr?'Texto recuperado por OCR. ':''}</small></div><div class="actions">${btn('read-page','Ler texto','small',`data-book="${p.book}" data-page="${p.page}"`)}${sourceLink(p)}</div></div>`).join('')}</div><div class="actions section-gap">${btn('lib-prev','← Anterior','small',libraryFilter.page===0?'disabled':'')}<small>Página ${libraryFilter.page+1} de ${pages}</small>${btn('lib-next','Próxima →','small',libraryFilter.page>=pages-1?'disabled':'')}</div></section>`:`<div class="book-grid">${C.books.map(b=>`<article class="book"><span class="chip">${b.pages} PÁGINAS</span><h3>${esc(b.title)}</h3><p>${esc(b.description||'Material fornecido para esta edição do criador de fichas.')}${b.machineTranslated?' Tradução automática; confira termos e regras.':''}</p><div class="actions">${sourceLink({...b,book:b.id,page:1})}${btn('search-book','Pesquisar neste livro','ghost small',`data-book="${b.id}"`)}</div></article>`).join('')}</div>`}<section class="panel section-gap"><div class="panel-head"><h2>A ficha oficial acompanha o programa</h2>${btn('source','Abrir ficha oficial','small','data-book="sheet" data-page="1"')}</div><p class="hint">A ficha em português exportada pelo botão PDF inclui os dados e referências do personagem. A ficha oficial de quatro páginas também fica disponível integralmente na biblioteca.</p><div class="actions">${btn('official-pdf','Exportar na ficha oficial','ghost small')}</div></section>`}
function bonusTargets(){return [['dice','Reserva de dados'],['difficulty','Dificuldade'],['initiative','Iniciativa'],['bloodMax','Limite de reserva de sangue'],['bloodPerTurn','Limite de sangue por turno'],['traitMax','Limite de característica'],...Object.entries(attrLabels).map(([k,label])=>['attribute:'+k,label]),...abilityDefs().map(a=>['ability:'+a.key,a.label])]}
function bonusesPage(c){return heading('Toda vantagem tem uma origem.','Bônus, penalidades e efeitos temporários da crônica.',btn('new-bonus','+ Novo modificador','primary'))+`<div class="actions">${btn('next-turn','Avançar turno','small')}${btn('end-scene','Encerrar cena','small')}</div><div class="list section-gap">${c.bonuses.map(b=>`<article class="list-item"><div><h3>${esc(b.name)} <span class="chip ${b.enabled?'green':''}">${b.enabled?'ATIVO':'INATIVO'}</span></h3><p>${b.value>=0?'+':''}${fmt(b.value)} em ${esc(bonusTargets().find(x=>x[0]===b.target)?.[1]||b.target)} · ${b.duration==='turns'?b.remaining+' turno(s)':b.duration==='scene'?'até encerrar a cena':'permanente'}</p><small>${esc(b.notes)}</small></div><div class="actions">${btn('toggle-bonus',b.enabled?'Desativar':'Ativar','small',`data-id="${b.id}"`)}${btn('edit-bonus','Editar','small',`data-id="${b.id}"`)}${btn('remove-bonus','Remover','danger ghost small',`data-id="${b.id}"`)}</div></article>`).join('')||empty('Registre o nome, o alvo, o valor e a duração do efeito.','new-bonus','Adicionar modificador')}</div><section class="panel section-gap"><h2>Como os bônus entram no teste</h2><p class="hint">Bônus em atributos e habilidades entram na soma automática da reserva. Bônus em Reserva de dados afetam também as reservas manuais. Dificuldade e Iniciativa têm alvos próprios. Ferimentos são aplicados pela rolagem quando o teste não é reflexivo. Valores altos ficam preservados; a reserva rolável tem um limite de processamento informado na mensagem de erro.</p></section>`}
function historyPage(){return heading('Você pode voltar uma noite.','Até 30 alterações recentes, guardadas neste dispositivo.',`<div class="actions">${btn('undo','↶ Desfazer','small',journal.undo.length?'':'disabled')}${btn('redo','↷ Refazer','small',journal.redo.length?'':'disabled')}</div>`)+`<section class="panel"><div class="journal">${journal.undo.slice().reverse().map((e,n)=>`<div><small>${new Date(e.time).toLocaleString('pt-BR')}</small><strong>${esc(e.label)}</strong><p>${e.changes.length} campo(s) / operação(ões)</p>${n===0?btn('undo','Desfazer esta alteração','small'):''}</div>`).join('')||empty('As próximas edições aparecem aqui.')}</div><p class="hint">O histórico local é limitado a 10 MB. Compartilhar ficha exporta o estado atual, sem suas versões anteriores. Atalhos Ctrl+Z / Ctrl+Y fora dos campos de texto.</p></section>`}
function openModal(title,content,actions=''){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${btn('close','×','ghost','aria-label="Fechar janela"')}</div>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!m.open)m.showModal()}
function closeModal(){$('#modal').close()}
function confirmAction(title,text,action){openModal(title,`<p>${esc(text)}</p>`,btn('close','Cancelar','ghost')+btn(action,'Confirmar','primary'))}
function labelOption(list){return ({disciplines:'disciplina',backgrounds:'antecedente',paths:'trilha / referência de poder',rituals:'ritual',merits:'qualidade',flaws:'defeito'})[list]||'opção'}
function optionEditor(list,existing=null,entry=null){const i=existing?structuredClone(existing):{id:R.uid(),name:entry?.name||'',rating:entry?.rating??entry?.level??(list==='rituals'?1:0),cost:Math.abs(entry?.cost??1),inClan:(O.clans?.find(c=>c.name===ch().clan)?.disciplines||[]).includes(entry?.name),granted:['power','combination'].includes(entry?.category),notes:'',book:entry?.book||'',page:entry?.page||0,discipline:entry?.discipline||''};window.editingOption={list,item:i,existing:!!existing};const choices=list==='disciplines'?O.disciplines||[]:list==='backgrounds'?O.backgrounds||[]:[];openModal(`${existing?'Editar':'Adicionar'} ${labelOption(list)}`,`<div class="field-grid"><div><label for="option-name">Nome</label><input id="option-name" value="${esc(i.name)}" maxlength="3000" list="known-options"><datalist id="known-options">${choices.map(x=>`<option value="${esc(x.name)}">${esc(x.label||x.name)}</option>`).join('')}</datalist></div><div><label for="option-value">${['merits','flaws'].includes(list)?'Custo em pontos (positivo)':'Pontos / nível'}</label><input id="option-value" type="number" min="0" step="1" value="${['merits','flaws'].includes(list)?i.cost:i.rating}"></div>${list==='disciplines'?`<label class="toggle-label"><input id="option-in-clan" type="checkbox" ${i.inClan?'checked':''}>Disciplina do clã / linhagem</label>`:''}${['backgrounds','paths','rituals'].includes(list)?`<label class="toggle-label"><input id="option-granted" type="checkbox" ${i.granted?'checked':''}>Concedido pela regra ou pelo narrador (sem custo)</label>`:''}${['paths','rituals'].includes(list)?`<div><label for="option-parent">Disciplina / feitiçaria de origem</label><input id="option-parent" value="${esc(i.discipline||'')}" placeholder="Ex.: Thaumaturgy, Necromancy"></div>`:''}<div><label for="option-book">Livro da referência</label><select id="option-book">${opts([['','Regra da crônica'],...C.books.map(b=>[b.id,b.title])],i.book)}</select></div><div><label for="option-page">Página do PDF (0 = sem página)</label><input id="option-page" type="number" min="0" value="${i.page||0}"></div></div>${entry?.costLabel?`<p class="hint">Custos previstos na fonte: ${esc(entry.costLabel)}. Escolha o custo da variante.</p>`:''}<div class="section-gap"><label for="option-notes">Escolhas, descrição e condições</label><textarea id="option-notes">${esc(i.notes)}</textarea></div>${entry?.text?`<details class="section-gap"><summary>Texto extraído da fonte</summary><div class="entry-text section-gap">${esc(entry.text)}</div></details>`:''}<div class="actions section-gap">${sourceLink(i)}</div><p class="hint">${list==='disciplines'?'Os quatro pontos iniciais vão para disciplinas do clã. Marque a origem para calcular o custo de experiência. Disciplinas físicas passivas entram nos dados correspondentes.':list==='backgrounds'?'Geração e Rebanho têm efeitos próprios. Ajustar o antecedente Geração oferece a sincronização da geração na ficha.':list==='rituals'?'Rituais concedidos pela disciplina podem ser marcados como gratuitos. Para aprender por experiência, registre o nível e use Comprar aumento, escolhendo Ritual.':list==='paths'?'Trilhas de feitiçaria têm custo próprio. Referências de poderes já incluídos numa disciplina devem ser marcadas como concedidas para não cobrar de novo.':'Qualidades gastam pontos de bônus; Defeitos geram crédito até o limite configurado.'}</p>`,btn('close','Cancelar','ghost')+btn('save-option','Salvar opção','primary'))}
function equipmentEditor(existing=null){window.editingEquipment=existing?structuredClone(existing):null;const i=existing||{name:'',quantity:1,weight:0,type:'item',damage:0,armor:0,penalty:0,equipped:false,notes:''};openModal(existing?'Editar equipamento':'Novo equipamento',`<div class="field-grid"><div><label for="eq-name">Nome</label><input id="eq-name" value="${esc(i.name)}"></div><div><label for="eq-type">Tipo</label><select id="eq-type">${opts([['item','Objeto'],['weapon','Arma'],['armor','Armadura']],i.type)}</select></div><div><label for="eq-quantity">Quantidade</label><input id="eq-quantity" type="number" min="0" value="${i.quantity}"></div><div><label for="eq-weight">Peso unitário em kg</label><input id="eq-weight" type="number" step="any" min="0" value="${i.weight||0}"></div><div><label for="eq-damage">Modificador de dano (ex.: Força + 2 → 2)</label><input id="eq-damage" type="number" value="${i.damage||0}"></div><div><label for="eq-armor">Dados de armadura</label><input id="eq-armor" type="number" min="0" value="${i.armor||0}"></div><div><label for="eq-penalty">Penalidade de Destreza da armadura</label><input id="eq-penalty" type="number" min="0" value="${Math.abs(i.penalty||0)}"></div><label class="toggle-label"><input id="eq-equipped" type="checkbox" ${i.equipped?'checked':''}>Equipado</label></div><div class="section-gap"><label for="eq-notes">Notas, tipo de dano e regras de uso</label><textarea id="eq-notes">${esc(i.notes)}</textarea></div><p class="hint">Armaduras equipadas entram na absorção e sua penalidade entra na Destreza. Dados de dano da arma são somados manualmente à reserva apropriada.</p>`,btn('close','Cancelar','ghost')+btn('save-equipment','Salvar equipamento','primary'))}
function bonusEditor(existing=null){window.editingBonus=existing?structuredClone(existing):null;const b=existing||{name:'',target:'dice',value:0,duration:'permanent',remaining:1,enabled:true,notes:''};openModal(existing?'Editar modificador':'Novo modificador',`<div class="field-grid"><div><label for="bonus-name">Origem / nome</label><input id="bonus-name" value="${esc(b.name)}"></div><div><label for="bonus-target">Alvo</label><select id="bonus-target">${opts(bonusTargets(),b.target)}</select></div><div><label for="bonus-value">Bônus / redutor</label><input id="bonus-value" type="number" value="${b.value}" step="1"></div><div><label for="bonus-duration">Duração</label><select id="bonus-duration">${opts([['permanent','Permanente'],['scene','Até encerrar a cena'],['turns','Número de turnos']],b.duration)}</select></div><div><label for="bonus-remaining">Turnos (se aplicável)</label><input id="bonus-remaining" type="number" min="1" value="${b.remaining||1}"></div><label class="toggle-label"><input id="bonus-enabled" type="checkbox" ${b.enabled?'checked':''}>Ativo</label></div><div class="section-gap"><label for="bonus-notes">Condição e referência</label><textarea id="bonus-notes">${esc(b.notes)}</textarea></div><p class="hint">Valores positivos e negativos permanecem iguais ao salvar e compartilhar. Um efeito de turnos expirado precisa de novo prazo antes de ser reativado.</p>`,btn('close','Cancelar','ghost')+btn('save-bonus','Salvar modificador','primary'))}
function xpChoices(type,c){return type==='attribute'?Object.entries(attrLabels):type==='ability'?abilityDefs().map(a=>[a.key,a.label]):type==='virtue'?Object.entries(virtueLabels(c)):type==='road'?[['road',roadLabel(c.road)]]:type==='willpower'?[['willpower','Força de Vontade']]:({discipline:c.disciplines,background:c.backgrounds,path:c.paths,ritual:c.rituals}[type]||[]).map(i=>[i.id,i.name+' · '+i.rating])}
function xpEditor(){openModal('Comprar aumento com experiência',`<div class="field-grid"><div><label for="xp-type">Tipo de característica</label><select id="xp-type">${opts((R.traitTypes||[]).map(t=>[t.key,t.label]),'attribute')}</select></div><div><label for="xp-key">Característica / opção</label><select id="xp-key">${opts(xpChoices('attribute',ch()),'strength')}</select></div><div class="span2"><label for="xp-story">História / capítulo desta compra</label><input id="xp-story" placeholder="Ex.: Crônica de Paris — capítulo 2"></div><div class="span2"><label for="xp-notes">Justificativa e observações</label><textarea id="xp-notes"></textarea></div><label class="toggle-label span2"><input id="xp-background" type="checkbox">Narrador autorizou compra de Antecedente com experiência</label></div><p id="xp-preview" class="hint"></p><p class="hint">Aumenta um ponto por compra; a mesma característica pode subir uma vez por história. Novas disciplinas, trilhas e habilidades usam os custos específicos. Adicione primeiro à ficha uma opção que ainda não existe; use valor zero para novas disciplinas/trilhas.</p>`,btn('close','Cancelar','ghost')+btn('confirm-xp','Comprar e registrar','primary'));previewXP()}
function previewXP(){const type=$('#xp-type').value,key=$('#xp-key').value,c=ch();let current=type==='attribute'?c.attributes[key]:type==='ability'?c.abilities[key]:type==='virtue'?c.virtues[key]:type==='road'?c.roadScore:type==='willpower'?c.willpower:({discipline:c.disciplines,background:c.backgrounds,path:c.paths,ritual:c.rituals}[type]||[]).find(i=>i.id===key)?.rating;const item=({discipline:c.disciplines,background:c.backgrounds,path:c.paths,ritual:c.rituals}[type]||[]).find(i=>i.id===key);try{if(current==null)throw Error('Adicione uma opção deste tipo à ficha antes de comprar.');const cost=R.experienceCost(type,current,{inClan:item?.inClan,allowBackground:$('#xp-background').checked,rating:current});$('#xp-preview').textContent=`Valor atual: ${current}. Custo da compra: ${cost} PE. Disponíveis: ${stats().xpAvailable} PE.`}catch(e){$('#xp-preview').textContent=e.message}}
function entryFrom(id){return searchStates.catalog.result?.rows.find(e=>e.id===id)|| (window.modalEntry?.id===id?window.modalEntry:null)}
function entryDetails(e){if(!e)throw Error('Refaça a pesquisa para recuperar essa opção.');window.modalEntry=e;openModal(e.label||e.name,`<p>${esc(categories[e.category]||e.category)} · ${esc(bookTitle(e.book))} · PDF p. ${e.page}</p><div class="entry-text">${esc(e.text)}</div>${e.ocr?'<p class="hint">Texto recuperado por OCR: confira o original.</p>':''}`,sourceLink(e)+btn('add-entry','Adicionar à ficha','primary',`data-id="${e.id}"`))}
function setClan(c,name){R.setClan(c,name);const option=O.clans?.find(i=>i.name===name);c.weakness=option?.weakness||''}
function setRoad(c,name){const option=O.roads?.find(i=>i.name===name),virtues=option?.virtues||[];R.setRoad(c,name,{moral:virtues[0]==='Conviction'?'conviction':'conscience',restraint:virtues[1]==='Instinct'?'instinct':'selfControl'})}
function log(text){const c=ch();c.rolls.push({id:R.uid(),label:'Registro da mesa',explanation:text,at:new Date().toISOString()});c.rolls=c.rolls.slice(-100);save()}
function applyHistory(direction){const label=journal.apply(state,direction,chars=>R.validateImport(R.pack(chars),{preserveIds:true}));if(!label)return;journal.suspended=true;try{save()}finally{journal.suspended=false}closeModal();render();toast(`${direction==='undo'?'Desfeito':'Refeito'}: ${label}`)}
function download(text,name,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportData(all=false){await flushSave();const data=R.pack(all?state.characters:[ch()]);const name=all?'Sangue-e-Cinzas-Backup':ch().name;const result=window.desktop?await desktop.export(data,name):(download(JSON.stringify(data,null,2),name+'.dav20.json'),true);if(result)toast(all?'Backup de todos os personagens exportado.':'Ficha exportada. Outra pessoa pode usar Importar para abrir uma cópia.')}
async function importData(raw){const imported=R.validateImport(raw);for(const c of imported)c.name+=' (importado)';state.characters.push(...imported);state.selected=imported[0].id;storageBlocked=false;editLabel='Importar fichas';save();view='resumo';render();toast(`${imported.length} ficha(s) importada(s).`)}
const actions={
 close:closeModal,guide:el=>{view=el.dataset.goto;render();window.scrollTo(0,0)},
 new:()=>openModal('Um novo Cainita',`<div><label for="new-name">Nome do personagem</label><input id="new-name" maxlength="200" placeholder="Nome nas noites"></div><p class="hint">Começa na 12ª geração, com a distribuição padrão de Dark Ages V20. Clã, Caminho, prioridades e regras de campanha podem ser ajustados.</p>`,btn('close','Cancelar','ghost')+btn('create-character','Criar personagem','primary')),
 'create-character':()=>{const c=R.create($('#new-name').value.trim()||'Novo Cainita');state.characters.push(c);state.selected=c.id;view='personagem';save();closeModal();render()},
 duplicate:()=>{const c=R.validateImport(R.pack([ch()]))[0];c.name+=' (cópia)';state.characters.push(c);state.selected=c.id;save();render();toast('Cópia independente criada.')},
 'delete-character':()=>confirmAction('Excluir personagem?','A ficha poderá ser recuperada pelo histórico recente. Exporte uma cópia para guardar em outro lugar.','confirm-delete-character'),
 'confirm-delete-character':()=>{state.characters=state.characters.filter(c=>c.id!==ch().id);if(!state.characters.length)state.characters=[R.create('Novo Cainita')];state.selected=state.characters[0].id;save();closeModal();render()},
 portrait:()=>$('#portrait-file').click(),'remove-portrait':()=>{ch().portrait='';save('portrait');render()},
 'trait-step':el=>{const c=ch(),g=el.dataset.group,k=el.dataset.key;c[g][k]=num(c[g][k]+Number(el.dataset.delta),'Característica',0);save(g);render()},
 'trait-dot':el=>{const c=ch(),g=el.dataset.group,k=el.dataset.key,v=Number(el.dataset.value);c[g][k]=c[g][k]===v?v-1:v;save(g);render()},
 'clan-disciplines':()=>{const clan=O.clans?.find(i=>i.name===ch().clan);if(!clan)throw Error('Escolha um clã do catálogo.');for(const name of clan.disciplines)if(!ch().disciplines.some(i=>R.normalize(i.name)===R.normalize(name))){const source=O.disciplines?.find(i=>i.name===name);ch().disciplines.push({id:R.uid(),name,rating:0,inClan:true,granted:false,notes:'',book:source?.book||clan.book,page:source?.page||clan.page})}save('disciplines');render();toast('Disciplinas adicionadas com zero pontos. Distribua os quatro pontos iniciais.')},
 'new-option':el=>optionEditor(el.dataset.list),'edit-option':el=>optionEditor(el.dataset.list,ch()[el.dataset.list].find(i=>i.id===el.dataset.id)),
 'save-option':()=>{const {list,item,existing}=window.editingOption,candidate=structuredClone(ch()),i={...item};i.name=$('#option-name').value.trim();if(!i.name)throw Error('Informe o nome da opção.');if(['merits','flaws'].includes(list))i.cost=num($('#option-value').value,'Custo');else i.rating=num($('#option-value').value,'Pontos / nível');i.notes=$('#option-notes').value;i.book=$('#option-book').value;i.page=num($('#option-page').value,'Página do PDF');if(i.book&&i.page>C.books.find(b=>b.id===i.book).pages)throw Error('A página ultrapassa o tamanho do livro.');if($('#option-in-clan'))i.inClan=$('#option-in-clan').checked;if($('#option-granted'))i.granted=$('#option-granted').checked;if($('#option-parent'))i.discipline=$('#option-parent').value.trim();const known=(list==='disciplines'?O.disciplines:list==='backgrounds'?O.backgrounds:[])?.find(x=>x.name===i.name);if(!i.book&&known){i.book=known.book;i.page=known.page}const index=candidate[list].findIndex(x=>x.id===i.id);if(existing)candidate[list][index]=i;else candidate[list].push(i);R.calculate(candidate);Object.assign(ch(),candidate);save();closeModal();render();if(list==='backgrounds'&&['generation','geracao'].includes(R.normalize(i.name)))toast('Antecedente Geração registrado. Use Sincronizar geração em Criação e evolução.')},
 'remove-option':el=>{window.removingOption={list:el.dataset.list,id:el.dataset.id};confirmAction('Remover opção?','Os custos serão recalculados. Experiência já gasta permanece no registro; use Desfazer para reverter uma compra.','confirm-remove-option')},
 'confirm-remove-option':()=>{const {list,id}=window.removingOption;ch()[list]=ch()[list].filter(i=>i.id!==id);save(list);closeModal();render()},
 'freeze-creation':()=>confirmAction('Concluir a distribuição inicial?','Os valores atuais serão guardados como base. Aumentos seguintes contarão como compras com pontos de bônus. Confira os avisos antes de continuar.','confirm-freeze'),
 'confirm-freeze':()=>{R.freezeCreation(ch());save();closeModal();render();toast('Base inicial registrada. Agora distribua os pontos de bônus.')},
 'enter-play':()=>confirmAction('Começar a crônica?','A criação será finalizada e as compras com experiência ficarão disponíveis. As pendências numéricas continuarão visíveis para conferência.','confirm-play'),
 'confirm-play':()=>{R.enterPlay(ch());save();closeModal();render();toast('Criação finalizada. Confira os avisos e comece a crônica.')},
 'reset-creation':()=>confirmAction('Redefinir a base de criação?','Os valores atuais passarão a ser tratados como distribuição inicial quando você concluir novamente a etapa. Não reduz atributos nem devolve experiência. Registre a regra da crônica; esta ação pode ser desfeita.','confirm-reset-creation'),
 'confirm-reset-creation':()=>{ch().creation.base=null;ch().creation.phase='allocation';save();closeModal();render()},
 'sync-generation':()=>{const points=ch().backgrounds.filter(i=>['generation','geracao'].includes(R.normalize(i.name))).reduce((n,i)=>n+i.rating,0);ch().generation=num(12-points,'Geração',3);save('generation');render()},
 'gain-xp':()=>{R.addExperience(ch(),num($('#xp-amount').value,'Experiência',1));save('experience');render()},
 'buy-xp':xpEditor,'confirm-xp':()=>{const result=R.buyWithXP(ch(),{type:$('#xp-type').value,key:$('#xp-key').value,story:$('#xp-story').value,notes:$('#xp-notes').value,allowBackground:$('#xp-background').checked});save();closeModal();render();toast(`${result.label}: ${result.from} → ${result.to}; ${result.cost} PE gastos.`)},
 'spend-blood':()=>{R.spend(ch(),'blood',num($('#blood-amount').value,'Sangue'));save('resources');render()},
 'gain-blood':()=>{R.recover(ch(),'blood',num($('#blood-amount').value,'Sangue'));save('resources');render()},
 'spend-willpower':()=>{R.spend(ch(),'willpower',1);save('resources');render()},
 'restore-willpower':()=>{R.recover(ch(),'willpower',1);save('resources');render()},
 'initial-blood':()=>{const result=R.startingBlood(ch());log(result.explanation);render();toast(result.explanation)},
 'start-night':()=>{R.startNight(ch());log('Despertou: gastou 1 sangue e recuperou 1 ponto de Força de Vontade, respeitando o máximo.');render()},
 'apply-damage':()=>{const result=R.applyDamage(ch(),$('#damage-type').value,num($('#damage-amount').value,'Dano'),{halveBashing:$('#halve-bashing').checked});log(result.explanation);render()},
 heal:()=>{const result=R.heal(ch(),$('#damage-type').value,1,{rested:$('#heal-rested').checked});log(`Curou 1 nível de ${({bashing:'contundente',lethal:'letal',aggravated:'agravado'})[result.type]} e gastou ${result.cost} sangue.`);render()},
 'reset-health':()=>confirmAction('Redefinir vitalidade?','Todos os ferimentos serão removidos e o estado ficará Ativo. O narrador deve autorizar essa recuperação. Pode ser desfeito no histórico.','confirm-reset-health'),
 'confirm-reset-health':()=>{ch().health={bashing:0,lethal:0,aggravated:0,state:'active'};save('health');closeModal();render()},
 condition:el=>{const x=el.dataset.condition,c=ch();c.conditions=c.conditions.includes(x)?c.conditions.filter(a=>a!==x):[...c.conditions,x];save('conditions');render()},
 roll:()=>{const c=ch(),s=stats(),a=$('#roll-attribute').value,b=$('#roll-ability').value,manual=$('#roll-pool').value;const mode=$('#roll-mode').value;const pool=manual===''?(a?attrValue(c,s,a):0)+(b?abilityValue(c,s,b):0):num(manual,'Reserva de dados');const result=R.roll(c,{pool,difficulty:num($('#roll-difficulty').value,'Dificuldade',2),ability:manual===''?b:undefined,modifier:num($('#roll-modifier').value,'Modificador',-R.MAX),specialty:$('#roll-specialty').checked,willpower:$('#roll-willpower').checked,reflexive:$('#roll-reflexive').checked,soak:mode==='soak',damage:mode==='damage'});if(result.willpowerCost)R.spend(c,'willpower',result.willpowerCost);result.id=R.uid();result.label=$('#roll-purpose').value||[a?attrLabels[a]:'',b?abilityLabel(b):''].filter(Boolean).join(' + ')||'Reserva manual';c.rolls.push(result);c.rolls=c.rolls.slice(-100);save();render();$('#last-roll').innerHTML=`<div class="session-result"><h3>${esc(result.label)}</h3><div class="dice-result">${esc(result.outcome)} · ${result.successes} sucesso(s)</div><div class="dice-chips">${result.dice.slice(0,120).map(d=>`<span>${d}</span>`).join('')}</div>${result.dice.length>120?`<p>${fmt(result.dice.length-120)} outros dados registrados. Distribuição: ${Array.from({length:10},(_,n)=>`${n+1}: ${result.dice.filter(d=>d===n+1).length}`).join(' · ')}</p>`:''}<p>${esc(result.explanation)}</p></div>`},
 initiative:()=>{const result=R.rollInitiative(ch());ch().rolls.push({...result,id:R.uid(),label:'Iniciativa',at:new Date().toISOString()});ch().rolls=ch().rolls.slice(-100);save('rolls');render();$('#last-roll').innerHTML=`<div class="session-result"><div class="dice-result">Iniciativa ${result.total}</div><p>${esc(result.explanation)}</p></div>`},
 journal:()=>{const text=$('#journal-text').value.trim();if(!text)return;ch().journal.push({id:R.uid(),at:new Date().toISOString(),text});save('journal');render();$('#journal-text').value=''},
 'clear-rolls':()=>confirmAction('Limpar rolagens?','O registro da mesa será limpo; as anotações do diário permanecem.','confirm-clear-rolls'),
 'confirm-clear-rolls':()=>{ch().rolls=[];save('rolls');closeModal();render()},
 'new-equipment':()=>equipmentEditor(),'edit-equipment':el=>equipmentEditor(ch().inventory.find(i=>i.id===el.dataset.id)),
 'save-equipment':()=>{const i={id:window.editingEquipment?.id||R.uid(),name:$('#eq-name').value.trim(),quantity:num($('#eq-quantity').value,'Quantidade'),weight:num($('#eq-weight').value,'Peso',0,false),type:$('#eq-type').value,damage:num($('#eq-damage').value,'Dano',-R.MAX),armor:num($('#eq-armor').value,'Dados de armadura'),penalty:num($('#eq-penalty').value,'Penalidade de Destreza'),equipped:$('#eq-equipped').checked,notes:$('#eq-notes').value,book:window.editingEquipment?.book||'',page:window.editingEquipment?.page||0};if(!i.name)throw Error('Informe o nome do item.');const index=ch().inventory.findIndex(x=>x.id===i.id);if(index<0)ch().inventory.push(i);else ch().inventory[index]=i;save('inventory');closeModal();render()},
 'remove-equipment':el=>{window.removingEquipment=el.dataset.id;confirmAction('Remover equipamento?','O item e seus efeitos serão removidos da ficha.','confirm-remove-equipment')},
 'confirm-remove-equipment':()=>{ch().inventory=ch().inventory.filter(i=>i.id!==window.removingEquipment);save('inventory');closeModal();render()},
 'new-bonus':()=>bonusEditor(),'edit-bonus':el=>bonusEditor(ch().bonuses.find(i=>i.id===el.dataset.id)),
 'save-bonus':()=>{const b={id:window.editingBonus?.id||R.uid(),name:$('#bonus-name').value.trim(),target:$('#bonus-target').value,value:num($('#bonus-value').value,'Modificador',-R.MAX),enabled:$('#bonus-enabled').checked,duration:$('#bonus-duration').value,remaining:num($('#bonus-remaining').value,'Turnos',1),notes:$('#bonus-notes').value};if(!b.name)throw Error('Informe a origem do modificador.');const index=ch().bonuses.findIndex(x=>x.id===b.id);if(index<0)ch().bonuses.push(b);else ch().bonuses[index]=b;save('bonuses');closeModal();render()},
 'toggle-bonus':el=>{const b=ch().bonuses.find(i=>i.id===el.dataset.id);if(!b.enabled&&b.duration==='turns'&&b.remaining===0)throw Error('O efeito expirou. Edite o prazo para reativá-lo.');b.enabled=!b.enabled;save('bonuses');render()},
 'remove-bonus':el=>{window.removingBonus=el.dataset.id;confirmAction('Remover modificador?','O modificador será removido e pode ser recuperado com Desfazer.','confirm-remove-bonus')},
 'confirm-remove-bonus':()=>{ch().bonuses=ch().bonuses.filter(i=>i.id!==window.removingBonus);save('bonuses');closeModal();render()},
 'next-turn':()=>{const expired=R.advanceTurn(ch());log('Turno avançado.'+(expired.length?' Expiraram: '+expired.join(', '):''));render()},
 'end-scene':()=>{R.endScene(ch());log('Cena encerrada; efeitos temporários foram desativados.');render()},
 undo:()=>applyHistory('undo'),redo:()=>applyHistory('redo'),
 entry:el=>entryDetails(entryFrom(el.dataset.id)),
 'add-entry':el=>{const e=entryFrom(el.dataset.id);if(!e)throw Error('Pesquise novamente essa opção.');if(['clan','bloodline'].includes(e.category)){setClan(ch(),e.name);save();closeModal();view='personagem';render();return}if(e.category==='road'){setRoad(ch(),e.name);save();closeModal();view='personagem';render();return}if(e.category==='archetype'){window.modalEntry=e;openModal('Usar arquétipo',`<p>${esc(e.label||e.name)}</p><div class="entry-text">${esc(e.text)}</div>`,btn('use-nature','Usar como Natureza','primary')+btn('use-demeanor','Usar como Comportamento'));return}if(['rule','setting'].includes(e.category)){ch().journal.push({id:R.uid(),at:new Date().toISOString(),text:`${e.name} — ${bookTitle(e.book)}, PDF p. ${e.page}\n${e.text}`});save('journal');closeModal();toast('Referência registrada no diário da crônica.');return}const list=({discipline:'disciplines',background:'backgrounds',merit:'merits',flaw:'flaws',ritual:'rituals',path:'paths',power:'paths',combination:'paths'})[e.category]||'paths';optionEditor(list,null,e)},
 'use-nature':()=>{ch().nature=window.modalEntry.label||window.modalEntry.name;save('nature');closeModal();view='personagem';render()},'use-demeanor':()=>{ch().demeanor=window.modalEntry.label||window.modalEntry.name;save('demeanor');closeModal();view='personagem';render()},
 'catalog-prev':()=>{catalogFilter.page--;render()},'catalog-next':()=>{catalogFilter.page++;render()},'lib-prev':()=>{libraryFilter.page--;render()},'lib-next':()=>{libraryFilter.page++;render()},
 'read-page':async el=>{const p=await workerRequest({kind:'page',book:el.dataset.book,page:Number(el.dataset.page)});openModal(bookTitle(p.book)+' · PDF p. '+p.page,`<div class="page-text">${esc(p.text)}</div>${p.ocr?'<p class="hint">Texto recuperado por OCR.</p>':''}`,sourceLink(p))},
 source:async el=>{if(!C.libraryReady)throw Error('Adicione seus PDFs ao acervo local conforme o README.');const book=C.books.find(x=>x.id===el.dataset.book);if(!book)throw Error('Livro não encontrado.');const page=num(el.dataset.page,'Página',1);if(window.desktop)await desktop.source(book.file,page);else window.open('livros/'+encodeURIComponent(book.file)+'#page='+page,'_blank','noopener')},
 'search-book':el=>{libraryFilter.book=el.dataset.book;libraryFilter.query='';render();$('#library-search').focus()},
 export:()=>exportData(),backup:()=>exportData(true),import:async()=>{if(window.desktop){const raw=await desktop.import();if(raw)await importData(raw)}else $('#import-file').click()},
 pdf:async()=>{if(window.desktop){const result=await desktop.pdf(VampirePrint.html(ch(),R));if(result)toast('PDF completo salvo.')}else{const w=window.open('','_blank');if(!w)throw Error('Permita a janela de impressão.');w.document.write(VampirePrint.html(ch(),R));w.document.close();setTimeout(()=>w.print(),300)}},
 'official-pdf':()=>{if(!window.desktop?.official)throw Error('A exportação oficial está disponível no programa para computador.');const warnings=VampirePrint.officialWarnings(ch(),R);if(warnings.length){openModal('Conferir a ficha oficial',`<p>A ficha original tem espaço fixo. O PDF completo em português guarda todos os detalhes.</p>${warnings.map(w=>`<div class="warn">${esc(w)}</div>`).join('')}`,btn('close','Cancelar','ghost')+btn('confirm-official','Exportar ficha oficial','primary'))}else return actions['confirm-official']()},
 'confirm-official':async()=>{const result=await desktop.official(ch());if(result){closeModal();toast('Ficha oficial preenchida e editável salva.')}}
};
const actionLabels={'save-option':'Editar opção','save-equipment':'Editar equipamento','save-bonus':'Salvar modificador','toggle-bonus':'Ativar / desativar modificador','confirm-remove-bonus':'Remover modificador','next-turn':'Avançar turno','end-scene':'Encerrar cena','create-character':'Criar personagem','confirm-delete-character':'Excluir personagem','duplicate':'Duplicar personagem','condition':'Alterar condição','roll':'Realizar teste','initiative':'Rolar iniciativa','apply-damage':'Aplicar dano','heal':'Curar ferimento','confirm-xp':'Comprar com experiência','confirm-freeze':'Concluir distribuição inicial','confirm-play':'Finalizar criação','confirm-reset-creation':'Redefinir base de criação'};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b)editLabel=actionLabels[b.dataset.action]||b.textContent.trim()||'Editar ficha'},true);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{if(b.dataset.view){view=b.dataset.view;render();window.scrollTo(0,0)}else if(b.dataset.character){state.selected=b.dataset.character;render();flushSave()}else if(actions[b.dataset.action])await actions[b.dataset.action](b)}catch(error){if(historyReady){state.characters=Array.from(journal.baseline.values(),x=>structuredClone(x));if(!state.characters.some(c=>c.id===state.selected))state.selected=state.characters[0]?.id;render()}toast(error.message||'Não foi possível concluir a ação.')}});
function setField(el){const c=ch(),keys=el.dataset.field.split('.');let target=c;for(const k of keys.slice(0,-1))target=target[k];const key=keys.at(-1),old=target[key];let value=el.type==='checkbox'?el.checked:el.value;if(keys[0]==='campaign')value=el.value.trim()===''?null:num(el.value,key);else if(el.type==='number')value=num(value,el.labels?.[0]?.textContent||key,0);if(key==='generation')value=num(value,'Geração',3);if(key==='clan')setClan(c,value);else if(key==='road')setRoad(c,value);else target[key]=value;try{R.calculate(c)}catch(error){target[key]=old;throw error}save(key==='clan'||key==='road'?null:keys[0]);el.setCustomValidity('')}
let searchTimer;
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){editLabel='Editar campo: '+(el.labels?.[0]?.textContent||el.dataset.field);el.setCustomValidity('');try{setField(el)}catch(error){el.setCustomValidity(error.message)}}if(el.dataset.specialty){editLabel='Editar especialidade';ch().specialties[el.dataset.specialty]=el.value;save('specialties')}if(['catalog-search','library-search'].includes(el.id)){const filter=el.id==='catalog-search'?catalogFilter:libraryFilter;filter.query=el.value;filter.page=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(view===(el.id==='catalog-search'?'catalogo':'biblioteca'))render()},120)}});
document.addEventListener('change',e=>{const el=e.target;try{if(el.dataset.trait){editLabel='Editar característica';const group=el.dataset.trait,key=el.dataset.key,old=ch()[group][key];ch()[group][key]=num(el.value,'Pontos de característica');try{R.calculate(ch())}catch(error){ch()[group][key]=old;throw error}save(group);render()}else if(el.dataset.resource){const key=el.dataset.resource,s=stats(),max=key==='blood'?s.bloodMax:s.willpowerMax;ch().resources[key]=R.number(el.value,'Recurso atual',0,max??R.MAX,true);editLabel='Editar recurso atual';save('resources');render()}else if(el.dataset.priority){const array=ch().creation[el.dataset.priority+'Priorities'],group=el.dataset.group,old=array.indexOf(group),next=Number(el.value);[array[old],array[next]]=[array[next],array[old]];editLabel='Alterar prioridades de criação';save('creation');render()}else if(el.dataset.field){el.setCustomValidity('');setField(el);if(el.tagName==='SELECT'||el.type==='checkbox')render()}else if(el.id==='catalog-category'){catalogFilter.category=el.value;catalogFilter.page=0;render()}else if(el.id==='catalog-book'){catalogFilter.book=el.value;catalogFilter.page=0;render()}else if(el.id==='library-book'){libraryFilter.book=el.value;libraryFilter.page=0;render()}else if(el.id==='xp-type'){$('#xp-key').innerHTML=opts(xpChoices(el.value,ch()),'');previewXP()}else if(['xp-key','xp-background'].includes(el.id))previewXP()}catch(error){el.setCustomValidity(error.message);toast(error.message)}});
$('#import-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(f){if(f.size>100*1024*1024)throw Error('Arquivo de ficha maior que 100 MB.');await importData(JSON.parse(await f.text()))}}catch(error){toast(error.message)}e.target.value=''});
$('#portrait-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>4*1024*1024)throw Error('Use PNG, JPG ou WebP de até 4 MB.');const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});ch().portrait=image;save('portrait');render()}catch(error){toast(error.message)}e.target.value=''});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&!e.altKey){const key=e.key.toLowerCase();if(key==='s'){e.preventDefault();flushSave().then(()=>toast('Ficha salva.'))}else if(!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&['z','y'].includes(key)){e.preventDefault();try{applyHistory(key==='y'||e.shiftKey?'redo':'undo')}catch(error){toast(error.message)}}}});
window.addEventListener('beforeunload',()=>{if(!window.desktop&&!storageBlocked){try{localStorage.setItem('sangue-e-cinzas-dav20',JSON.stringify(persisted()))}catch{}}else flushSave()});
async function init(){if(window.desktop?.library){try{const metadata=await desktop.library();if(metadata)Object.assign(C,metadata,{libraryReady:true})}catch(error){toast(error.message)}}try{const raw=window.desktop?await desktop.load():JSON.parse(localStorage.getItem('sangue-e-cinzas-dav20')||'null');if(raw?.characters?.length){state.characters=R.validateImport(raw,{preserveIds:true});state.selected=state.characters.some(c=>c.id===raw.selected)?raw.selected:state.characters[0].id;journal.restore(raw.audit,state.characters);if(raw.recovered)toast('Ficha recuperada da cópia de segurança automática.')}}catch(error){storageBlocked=true;lastSave='Erro ao ler dados — importe um backup';toast(error.message)}if(!state.characters.length){state.characters=[R.create('Meu primeiro Cainita')];state.selected=state.characters[0].id;journal.reset(state.characters)}historyReady=true;render()}
init();
